values.content:
Route this support ticket.

Ticket: {{ $json.ticketId }}
Subject: {{ $json.ticketSubject }}
Customer: {{ $json.customerName || 'unknown' }}{{ $json.customerEmail ? ' <' + $json.customerEmail + '>' : '' }}
Plan: {{ $json.customerPlan || 'unknown' }}
Account age: {{ $json.accountAge ? $json.accountAge + ' days' : 'unknown' }}
Previous tickets: {{ $json.previousTicketCount }}
Product: {{ $json.productName || 'not specified' }}

Available routing teams:
{{ $json.routingTeams.map(t=>t.name+' ('+t.specialties.join('+')+')').join(', ') }}

Ticket content:
{{ $json.ticketBody }}

Return JSON:
{"classification":{"category":"bug|feature_request|how_to|billing|account|integration|data|performance|security|other","subcategory":"more specific classification","severity":"critical|high|medium|low","severity_rationale":"why this severity"},"routing":{"recommended_team":"team name from the provided list","routing_rationale":"why this team","escalate":false,"escalation_reason":null,"estimated_resolution_time":"e.g. 2-4 hours"},"ticket_analysis":{"real_problem":"what the customer actually needs — may differ from what they asked","churn_risk":"high|medium|low|none","churn_signals":"specific language or context that indicates churn risk","customer_sentiment":"frustrated|neutral|positive|confused","urgency_signals":["specific phrases or context that indicate urgency"]},"suggested_first_response":"a specific 3-5 sentence response the support agent can adapt — acknowledges the specific issue, not generic","internal_notes":"what the agent should know before responding — context, likely cause, what to check first","similar_issues_to_check":["related areas to investigate or ask about"]}
